head.r/main.tf:
terraform {
  backend "s3" {}
}
variable "items" {}
resource "aws_security_group" "s" {
  name = "s"
  dynamic "ingress" {
    for_each = var.items
    content {
      from_port   = 22
      to_port     = 22
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    }
  }
}

terraform {
  backend "s3" {}
}
variable "items" {}
data "aws_iam_policy_document" "d" {
  dynamic "statement" {
    for_each = var.items
    content {
      actions = ["sts:AssumeRole"]
      principals {
        type        = "AWS"
        identifiers = ["*"]
      }
    }
  }
}
resource "aws_iam_role" "r" {
  name               = "r"
  assume_role_policy = data.aws_iam_policy_document.d.json
}

